Here's a complete example with both `DataRow` and `DynamicData` approaches:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace PriceCalculator.Tests;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: best for simple inline values ---

    [TestMethod]
    [DataRow(1, 10.00, 10.00)]
    [DataRow(5, 3.50, 17.50)]
    [DataRow(0, 99.99, 0.00)]
    [DataRow(100, 0.01, 1.00)]
    public void CalculateTotal_ReturnsExpected(int quantity, double price, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)price);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 0.10, 90.00, DisplayName = "10% off $100")]
    [DataRow(50.00, 0.25, 37.50, DisplayName = "25% off $50")]
    [DataRow(200.00, 0.00, 200.00, DisplayName = "No discount")]
    [DataRow(80.00, 1.00, 0.00, DisplayName = "100% discount")]
    public void ApplyDiscount_ReturnsExpected(double total, double discount, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)total, (decimal)discount);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: best for complex objects or computed test cases ---

    public static IEnumerable<object[]> BulkDiscountCases =>
    [
        [1000m, 0.15m, 850.00m],
        [49.99m, 0.50m, 24.995m],
        [0m, 0.10m, 0m],
    ];

    [TestMethod]
    [DynamicData(nameof(BulkDiscountCases))]
    public void ApplyDiscount_BulkCases_ReturnsExpected(decimal total, decimal discount, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discount);
        Assert.AreEqual(expected, result);
    }

    // DynamicData with a method (useful for generating cases programmatically)
    public static IEnumerable<object[]> GetEdgeCases()
    {
        yield return [int.MaxValue, 0.01m, (decimal)int.MaxValue * 0.01m];
        yield return [1, decimal.MaxValue, decimal.MaxValue];
    }

    [TestMethod]
    [DynamicData(nameof(GetEdgeCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_EdgeCases_ReturnsExpected(int quantity, decimal price, decimal expected)
    {
        var result = _calculator.CalculateTotal(quantity, price);
        Assert.AreEqual(expected, result);
    }

    // --- Negative tests ---

    [TestMethod]
    [DataRow(-1, 10.00)]
    [DataRow(1, -5.00)]
    public void CalculateTotal_InvalidInput_Throws(int quantity, double price)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(quantity, (decimal)price));
    }

    [TestMethod]
    [DataRow(100.00, -0.01)]
    [DataRow(100.00, 1.01)]
    public void ApplyDiscount_InvalidRate_Throws(double total, double discount)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)total, (decimal)discount));
    }
}
```

**Key best practices shown:**

| Practice | Why |
|----------|-----|
| `DataRow` for simple primitives | Inline, readable, no boilerplate |
| `DynamicData` property/method | Supports `decimal`, complex objects, computed sets |
| `DisplayName` on DataRow | Readable test names in explorer |
| `[TestInitialize]` | Fresh instance per test, no shared state |
| Separate negative tests | Clear pass/fail semantics |
| `double` in DataRow (cast to `decimal`) | DataRow only supports compile-time constants |

**Note:** `DataRow` doesn't support `decimal` literals directly — use `double` and cast, or switch to `DynamicData` for exact decimal values.
